def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for h in history:
        if h[1] == 'D':
            opp_def += 1

    if opp_def == 0:
        if n < 4:
            return 'C'
        if n == 4:
            return 'D'
        if n == 5:
            return 'C'
        if n == 6:
            if history[5][1] == 'D':
                return 'C'
            else:
                return 'D'
        if n > 6:
            return 'D'

    if n == 6:
        if len(history) >= 5 and history[4][0] == 'D':
            all_cc = True
            for i in range(4):
                if history[i][0] != 'C' or history[i][1] != 'C':
                    all_cc = False
                    break
            if all_cc and history[5][1] == 'D':
                return 'C'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        return 'D'
    else:
        return 'C'
